\documentclass{article}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{pgfplotstable}

\begin{document}

\begin{tikzpicture}
\begin{axis}[
    title={折线图示例},
    xlabel={X轴标签},
    ylabel={Y轴标签},
    xmin=0, xmax=10,
    ymin=0, ymax=100,
    xtick={0,2,4,6,8,10},
    ytick={0,20,40,60,80,100},
    legend pos=north west,
    grid=major,
    width=12cm,
    height=8cm,
]

% 第一条折线
\addplot [
    color=blue,
    mark=square,
    ]
    coordinates {
    (1, 10)
    (2, 25)
    (3, 45)
    (4, 60)
    (5, 75)
    (6, 85)
    (7, 90)
    (8, 95)
    (9, 98)
    (10, 100)
    };
    \addlegendentry{数据集A}

% 第二条折线
\addplot [
    color=red,
    mark=triangle,
    ]
    coordinates {
    (1, 5)
    (2, 15)
    (3, 30)
    (4, 50)
    (5, 65)
    (6, 75)
    (7, 82)
    (8, 88)
    (9, 92)
    (10, 95)
    };
    \addlegendentry{数据集B}

% 第三条折线
\addplot [
    color=green,
    mark=*,
    ]
    coordinates {
    (1, 8)
    (2, 20)
    (3, 35)
    (4, 55)
    (5, 70)
    (6, 80)
    (7, 87)
    (8, 92)
    (9, 96)
    (10, 98)
    };
    \addlegendentry{数据集C}

\end{axis}
\end{tikzpicture}

\end{document}
